        BigDecimal overdue = Snapshot.trimmed(treePeople.stream().map(TreePerson::overdueTotal).toList());
        return new Consolidated(distinctPeople(treePeople), due, overdue, grades, statuses, treePeople,
                overdueCount);
    }

